(() => {
  const button=document.querySelector('#readBtn'); if(!button)return;
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const labels={'工作':'權責、方向與成果','財運':'收入、資源與風險','感情':'互動、界線與承諾','健康':'身心節奏與承受力','家庭／人際':'關係角色與界線','學業／方向':'能力、選擇與長線路徑','其他':'問題核心與下一步'};
  const render=()=>{const method=document.querySelector('.method.active')?.dataset.name,box=document.querySelector('.rich-method-result');if(!box||!['八字','印度占星'].includes(method))return;const topic=document.querySelector('#topicChoice')?.dataset.value||'工作',q=document.querySelector('#question')?.value.trim()||'目前最重要的選擇',bazi=method==='八字';const items=bazi?[['日主','日主代表本人核心；強弱要連月令、根氣、透干及全盤五行判斷。',`放返入「${topic}」：觀察你壓力下點樣承受，以及需要咩支援。`],['四柱','年柱看背景，月柱看成長基礎，日柱看本人與親密互動，時柱看後期發展。',`將「${topic}」拆成根源、現況、內在需要及下一階段成果。`],['十神','十神分類同伴、學習、責任、表達、財務，睇資源是否承托責任。',`針對「${topic}」列出得到咩、付出咩、誰可支援及最壞情況。`],['大運／流年／流月','大運約十年、流年一年、流月一月，是節奏參考，不是必然事件。',`未來 7 日收集「${topic}」資料，1 至 3 個月後按現實結果調整。`]]:[['Lagna','Lagna 是出生時東方地平線上升點，反映外在反應、行動方式及人生入口。',`喺「${topic}」上，留意你第一個反應係主動、觀望定保護自己。`],['Moon sign','Moon sign 反映情緒反應、習慣及壓力下的安全感，不是單一性格標籤。',`處理「${topic}」時，先講清楚你需要的穩定、信任、空間或回應速度。`],['Bhava','Bhava 將行星功能放入工作、財務、關係等生活領域。',`將「${topic}」拆成資源、責任、關係、身心及結果幾個領域。`],['Nakshatra／Dasha','Nakshatra 細分月亮心理模式，Dasha 讀較長行星周期，精確版本要由完整星曆覆核。',`將時間窗口當提醒，先做一個同「${topic}」有關的小測試。`]];box.innerHTML=`<div class="rich-method-head"><span>${bazi?'METHOD READING':'SIDEREAL READING'}</span><strong>${method} · ${labels[topic]||labels['其他']}</strong><small>問題：「${esc(q)}」 · 目前範疇：${esc(topic)}</small></div><div class="rich-method-grid">${items.map(x=>`<section class="rich-method-section"><button class="rich-method-term">${x[0]}</button><h4>${x[1]}</h4><p class="rich-method-action"><b>對${esc(topic)}的實際影響：</b>${x[2]}</p></section>`).join('')}</div>`;};button.addEventListener('click',()=>setTimeout(render,420));})();
